const http = require('http');
const { Pool } = require('generic-pool');
const crypto = require('crypto');

// Model registry with approved inference backends
const MODEL_REGISTRY = {
  'text-classifier': { module: './models/text_classifier', method: 'predict' },
  'sentiment-v2': { module: './models/sentiment', method: 'analyze' },
  'ner-extract': { module: './models/ner', method: 'extract' }
};

// Connection pool for model worker processes
const workerPool = {
  _pools: new Map(),
  _config: { max: 10, min: 2, idleTimeoutMillis: 30000 },

  getPool(modelId) {
    if (!this._pools.has(modelId)) {
      this._pools.set(modelId, { active: 0, idle: [] });
    }
    return this._pools.get(modelId);
  }
};

// Stored SHA-256 hashes of valid API keys (in production, load from secure config/secret store)
const VALID_API_KEY_HASHES = new Set(
  (process.env.API_KEY_HASHES || '').split(',').map(h => h.trim()).filter(Boolean)
);

// Constant-time comparison of a candidate hash against the set of valid hashes
function isValidTokenHash(hashHex) {
  const candidate = Buffer.from(hashHex, 'hex');
  let matched = false;
  for (const stored of VALID_API_KEY_HASHES) {
    const storedBuf = Buffer.from(stored, 'hex');
    if (storedBuf.length === candidate.length &&
        crypto.timingSafeEqual(storedBuf, candidate)) {
      matched = true;
    }
  }
  return matched;
}

// Middleware: request authentication
function authenticateRequest(req) {
  const token = req.headers['x-api-key'];
  if (!token || token.length < 32) return false;
  const hash = crypto.createHash('sha256').update(token).digest('hex');
  // Compare against stored valid API key hashes (constant-time)
  return isValidTokenHash(hash);
}

// Model loader with caching
const modelCache = new Map();

function resolveModelConfig(modelId, requestOptions) {
  const baseConfig = MODEL_REGISTRY[modelId];
  if (!baseConfig) return null;

  // Merge base config with request-level overrides for A/B testing
  const resolved = { ...baseConfig };

  // Allow method override for canary deployments
  if (requestOptions && requestOptions.methodOverride) {
    const allowedMethods = ['predict', 'analyze', 'extract', 'classify', 'embed'];
    if (allowedMethods.includes(requestOptions.methodOverride)) {
      resolved.method = requestOptions.methodOverride;
    }
  }

  return resolved;
}

// The inference dispatcher - handles routing to correct model backend
function createInferenceContext(config, inputData) {
  return {
    modelModule: config.module,
    entryPoint: config.method,
    payload: inputData,
    timestamp: Date.now()
  };
}

// Execute inference with connection pool management
async function executeInference(context, pool) {
  pool.active++;

  try {
    // Dynamic dispatch to model backend
    const backend = loadBackend(context.modelModule);
    const result = backend[context.entryPoint](context.payload);
    return { success: true, result, latency: Date.now() - context.timestamp };
  } finally {
    pool.active--;
  }
}

function loadBackend(modulePath) {
  if (modelCache.has(modulePath)) return modelCache.get(modulePath);

  // Simulated model loading - in production this loads TF/ONNX models
  const backend = {
    predict: (data) => ({ label: 'positive', score: 0.95 }),
    analyze: (data) => ({ sentiment: 'neutral', confidence: 0.87 }),
    extract: (data) => ({ entities: [] }),
    classify: (data) => ({ category: 'general', score: 0.91 }),
    embed: (data) => ({ vector: new Array(768).fill(0) })
  };

  modelCache.set(modulePath, backend);
  return backend;
}

// Allowed entry points for inference execution
const ALLOWED_ENTRY_POINTS = new Set(['predict', 'analyze', 'extract', 'classify', 'embed']);

// Request handler with pipeline processing
async function handleInferenceRequest(req, res) {
  if (!authenticateRequest(req)) {
    res.writeHead(401);
    return res.end(JSON.stringify({ error: 'Unauthorized' }));
  }

  let body = '';
  for await (const chunk of req) body += chunk;

  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch (e) {
    res.writeHead(400);
    return res.end(JSON.stringify({ error: 'Invalid JSON' }));
  }

  const { model, input, options } = parsed;

  if (!model || typeof model !== 'string') {
    res.writeHead(400);
    return res.end(JSON.stringify({ error: 'Model ID required' }));
  }

  // Resolve model configuration with request options
  const config = resolveModelConfig(model, options);
  if (!config) {
    res.writeHead(404);
    return res.end(JSON.stringify({ error: 'Model not found' }));
  }

  // Build inference context and execute
  const context = createInferenceContext(config, input);

  // Apply any context-level transforms from pipeline config
  if (options && options.pipeline) {
    applyPipelineTransforms(context, options.pipeline);
  }

  // Final validation: ensure entryPoint is in allowed set after all transforms
  if (!ALLOWED_ENTRY_POINTS.has(context.entryPoint)) {
    res.writeHead(400);
    return res.end(JSON.stringify({ error: 'Invalid inference method' }));
  }

  const pool = workerPool.getPool(model);
  const result = await executeInference(context, pool);

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(result));
}

// Pipeline transform application for multi-stage inference
function applyPipelineTransforms(context, pipeline) {
  if (!Array.isArray(pipeline)) return;

  for (const stage of pipeline) {
    if (stage.type === 'preprocess' && stage.fn) {
      // Apply named preprocessing function
      const preprocessors = {
        'lowercase': (ctx) => { ctx.payload = String(ctx.payload).toLowerCase(); },
        'trim': (ctx) => { ctx.payload = String(ctx.payload).trim(); },
        'tokenize': (ctx) => { ctx.payload = String(ctx.payload).split(/\s+/); }
      };
      if (preprocessors[stage.fn]) preprocessors[stage.fn](context);
    }
    if (stage.type === 'route' && stage.target) {
      // Dynamic routing: update context entry point based on pipeline
      // Only allow known safe methods
      if (ALLOWED_ENTRY_POINTS.has(stage.target)) {
        context.entryPoint = stage.target;
      }
    }
  }
}

const server = http.createServer(handleInferenceRequest);
server.listen(3000, () => console.log('ML Inference Server on :3000'));
